CREATE TABLE IF NOT EXISTS users (id VARCHAR(80) PRIMARY KEY, salt VARCHAR(128) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS agents (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL, provider VARCHAR(24) NOT NULL, name VARCHAR(120) NOT NULL, token_hash VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS permissions (owner_id VARCHAR(80) NOT NULL, agent_id VARCHAR(80) NOT NULL, scope VARCHAR(40) NOT NULL, bits INT NOT NULL, expires_at BIGINT NOT NULL DEFAULT 0, tx_hash VARCHAR(100), PRIMARY KEY(owner_id,agent_id,scope));
CREATE TABLE IF NOT EXISTS memories (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL, canonical_key VARCHAR(200) NOT NULL, project VARCHAR(100) NOT NULL, scope VARCHAR(40) NOT NULL, type VARCHAR(40) NOT NULL, current_version INT NOT NULL, status VARCHAR(20) NOT NULL, UNIQUE(owner_id,project,scope,canonical_key));
CREATE TABLE IF NOT EXISTS versions (memory_id VARCHAR(80) NOT NULL, version INT NOT NULL, content TEXT NOT NULL, content_hash VARCHAR(100) NOT NULL, source_agent VARCHAR(80) NOT NULL, confidence DOUBLE PRECISION NOT NULL, importance DOUBLE PRECISION NOT NULL, created_at BIGINT NOT NULL, valid_to BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(memory_id,version));
CREATE TABLE IF NOT EXISTS proposals (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL, payload TEXT NOT NULL, memory_id VARCHAR(80), expected_version INT NOT NULL, state VARCHAR(20) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL, actor VARCHAR(80) NOT NULL, action VARCHAR(40) NOT NULL, resource VARCHAR(200) NOT NULL, decision VARCHAR(20) NOT NULL, tx_hash VARCHAR(100), created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS anchors (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL, root VARCHAR(100) NOT NULL, leaves TEXT NOT NULL, tx_hash VARCHAR(100), created_at BIGINT NOT NULL);
